#include <stdio.h>

static char grid[128][128];

int main(void) {
    int L, C;
    if (scanf("%d %d", &L, &C) != 2) return 0;

    for (int i = 0; i < L; i++) {
        scanf("%127s", grid[i]);
    }

    /* localizar a posicao inicial 'o' */
    int cr = 0, cc = 0;
    for (int i = 0; i < L; i++) {
        for (int j = 0; j < C; j++) {
            if (grid[i][j] == 'o') { cr = i; cc = j; }
        }
    }

    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    int pr = -1, pc = -1; /* celula de onde viemos */
    long guard = (long)L * (long)C + 10; /* caminho simples tem no maximo L*C celulas */

    while (guard-- > 0) {
        int nr = -1, nc = -1;
        for (int d = 0; d < 4; d++) {
            int r2 = cr + dr[d];
            int c2 = cc + dc[d];
            if (r2 < 0 || r2 >= L || c2 < 0 || c2 >= C) continue;
            if (grid[r2][c2] != 'H') continue;
            if (r2 == pr && c2 == pc) continue; /* nao voltar */
            nr = r2; nc = c2;
            break; /* pelas garantias do problema, ha no maximo um candidato */
        }
        if (nr < 0) break; /* fim do trajeto */
        pr = cr; pc = cc;
        cr = nr; cc = nc;
    }

    printf("%d %d\n", cr + 1, cc + 1);
    return 0;
}
